<?php
 namespace App\Http\Middleware; use Closure; use Illuminate\Http\Request; use Illuminate\Support\Facades\App; use Illuminate\Support\Facades\Session; class SetLocale { protected $supportedLocales = ['id', 'en']; public function handle(Request $request, Closure $next) { if ($request->has('lang') && in_array($request->query('lang'), $this->supportedLocales)) { $locale = $request->query('lang'); Session::put('locale', $locale); } elseif (Session::has('locale') && in_array(Session::get('locale'), $this->supportedLocales)) { $locale = Session::get('locale'); } else { $locale = config('app.locale', 'id'); } App::setLocale($locale); return $next($request); } } 